INSERT IGNORE INTO peliculas (tmdb_id, titulo, tipo, descripcion, imagen_url, fecha_lanzamiento, generos) VALUES
(550, 'Fight Club', 'movie', 'An insomniac office worker and a devil-may-care soapmaker form an underground fight club that evolves into something much, much more.', 'https://image.tmdb.org/t/p/w500/bptfVGEQuv6vDqwYRjtt7EwZa6t.jpg', '1999-10-15', 'Drama'),
(278, 'The Shawshank Redemption', 'Película', 'Framed in the 1940s for the double murder of his wife and her lover, upstanding banker Andy Dufresne begins a new life at the Shawshank prison.', 'https://image.tmdb.org/t/p/w200/q6y0Go1tsGEsmtFryDOJo3dEmqu.jpg', '1994-09-23', 'Drama,Crime'),
(238, 'The Godfather', 'Película', 'Spanning the years 1945 to 1955, a chronicle of the fictional Italian-American Corleone crime family.', 'https://image.tmdb.org/t/p/w200/3bhkrj58Vtu7enYsRolD1fZdja1.jpg', '1972-03-14', 'Drama,Crime'),
(155, 'The Dark Knight', 'Película', 'Batman raises the stakes in his war on crime. With the help of Lt. Jim Gordon and District Attorney Harvey Dent, Batman sets out to dismantle the remaining criminal organizations that plague the streets.', 'https://image.tmdb.org/t/p/w200/qJ2tW6WMUDux911r6m7haRef0WH.jpg', '2008-07-18', 'Drama,Action,Crime'),
(13, 'Forrest Gump', 'Película', 'A man with a low IQ has accomplished great things in his life and been present during significant historic events.', 'https://image.tmdb.org/t/p/w200/arw2vcBveWOVZr6pxd9XTd1TdQa.jpg', '1994-07-06', 'Comedy,Drama,Romance'),
(122, 'The Lord of the Rings: The Return of the King', 'Película', 'Aragorn is revealed as the heir to the ancient kings as he, Gandalf and the other members of the broken fellowship struggle to save Gondor from Sauron\'s forces.', 'https://image.tmdb.org/t/p/w200/rCzpDGLbOoPwLjy3OAm5NUPOTrC.jpg', '2003-12-01', 'Adventure,Fantasy,Action'),
(769, 'GoodFellas', 'Película', 'The true story of Henry Hill, a half-Irish, half-Sicilian Brooklyn kid who is adopted by neighbourhood gangsters at an early age.', 'https://image.tmdb.org/t/p/w200/aKuFiU82s5ISJpGZp7YkIr3kCU.jpg', '1990-09-12', 'Drama,Crime'),
(120, 'The Lord of the Rings: The Fellowship of the Ring', 'Película', 'Young hobbit Frodo Baggins, after inheriting a mysterious ring from his uncle Bilbo, must leave his home in order to keep it from falling into the hands of its evil creator.', 'https://image.tmdb.org/t/p/w200/6oom5QYQ2yQTMJIbnvbkBL9cHo6.jpg', '2001-12-18', 'Adventure,Fantasy,Action'),
(121, 'The Lord of the Rings: The Two Towers', 'Película', 'Frodo and Sam are trekking to Mordor to destroy the One Ring of Power while Gimli, Legolas and Aragorn search for the orc-captured Merry and Pippin.', 'https://image.tmdb.org/t/p/w200/5VTN0pR8gcqV3EPUHHfMGnJYN9.jpg', '2002-12-18', 'Adventure,Fantasy,Action'),
(680, 'Pulp Fiction', 'Película', 'A burger-loving hit man, his philosophical partner, a drug-addled gangster\'s moll and a washed-up boxer converge in this sprawling, comedic crime caper.', 'https://image.tmdb.org/t/p/w200/d5iIlFn5s0ImszYzBPb8JPIfbXD.jpg', '1994-09-10', 'Thriller,Crime'),
(429, 'The Silence of the Lambs', 'Película', 'Clarice Starling is a top student at the FBI\'s training academy. Jack Crawford wants Clarice to interview Dr. Hannibal Lecter, a brilliant psychiatrist who is also a violent psychopath.', 'https://image.tmdb.org/t/p/w200/uS9m8OBk1A8eM9I042bx8XXpqAq.jpg', '1991-02-14', 'Crime,Drama,Thriller'),
(389, '12 Angry Men', 'Película', 'The defense and the prosecution have rested and the jury is filing into the jury room to decide if a young Spanish-American is guilty or innocent of murdering his father.', 'https://image.tmdb.org/t/p/w200/ow3wq89wM8qd5X7hWKxiRfsFf9C.jpg', '1957-04-10', 'Drama'),
(510, 'One Flew Over the Cuckoo\'s Nest', 'Película', 'A petty criminal fakes insanity to serve his sentence in a mental ward rather than prison. He soon finds himself as a leader to the other patients—and an enemy to the cruel, domineering nurse who runs the ward.', 'https://image.tmdb.org/t/p/w200/3jcbDmRFiQ83drXNOvRDeKHxS0C.jpg', '1975-11-19', 'Drama'),
(129, 'Spirited Away', 'Película', 'A young girl, Chihiro, becomes trapped in a strange new world of spirits. When her parents undergo a mysterious transformation, she must call upon the courage she never knew she had to free her family.', 'https://image.tmdb.org/t/p/w200/39wmItIWsg5sZMyRUHLkWBcuNKq.jpg', '2001-07-20', 'Animation,Family,Fantasy'),
(603, 'The Matrix', 'Película', 'Set in the 22nd century, The Matrix tells the story of a computer hacker who joins a group of underground insurgents fighting the vast and powerful computers who now rule the earth.', 'https://image.tmdb.org/t/p/w200/f89U3ADr1oiB1s9GkdPOEpXUk5H.jpg', '1999-03-31', 'Action,Sci-Fi'),
(1399, 'Breaking Bad', 'Serie', 'When Walter White, a New Mexico chemistry teacher, is diagnosed with Stage III cancer and given a prognosis of only two years left to live.', 'https://image.tmdb.org/t/p/w200/ggFHVNu6YYI5L9pCfOacjizRGt.jpg', '2008-01-20', 'Crime,Drama,Thriller'),
(84958, 'Loki', 'Serie', 'After stealing the Tesseract during the events of “Avengers: Endgame,” an alternate version of Loki is brought to the mysterious Time Variance Authority.', 'https://image.tmdb.org/t/p/w200/kEl2t3OhXc3Zb9FBh1AuYzRTgZp.jpg', '2021-06-09', 'Action,Adventure,Fantasy'),
(66732, 'Stranger Things', 'Serie', 'When a young boy vanishes, a small town uncovers a mystery involving secret experiments, terrifying supernatural forces, and one strange little girl.', 'https://image.tmdb.org/t/p/w200/49WJfeN0moxb9IPfGn8AIqMGskD.jpg', '2016-07-15', 'Drama,Fantasy,Horror'),
(76479, 'The Boys', 'Serie', 'A group of vigilantes known informally as “The Boys” set out to take down corrupt superheroes with no more than blue-collar grit and a willingness to fight dirty.', 'https://image.tmdb.org/t/p/w200/stTEycfG9928HYGEISBFaG1ngjM.jpg', '2019-07-25', 'Sci-Fi,Action,Comedy'),
(60625, 'Rick and Morty', 'Serie', 'Rick is a mentally-unbalanced but scientifically-gifted old man who has recently reconnected with his family.', 'https://image.tmdb.org/t/p/w200/cvhNj9eoRBe5SxjCbQTkh05UP5.jpg', '2013-12-02', 'Animation,Comedy,Sci-Fi'),
(456, 'The Usual Suspects', 'Película', 'Held in an L.A. interrogation room, Verbal Kint attempts to convince the feds that a mythic crime lord, Keyser Soze, not only exists, but was also responsible for drawing him and his four partners into a multi-million dollar heist.', 'https://image.tmdb.org/t/p/w200/9p6X2uaLMwNkeO1y4o0XaiwVgc.jpg', '1995-07-19', 'Drama,Mystery,Crime'),
(807, 'Se7en', 'Película', 'Two homicide detectives are on a desperate hunt for a serial killer whose crimes are based on the "seven deadly sins" in this dark and haunting film.', 'https://image.tmdb.org/t/p/w200/6yoghtyTp4QHk0OYYn5pTLF2BsM.jpg', '1995-09-22', 'Crime,Mystery,Thriller'),
(500, 'Reservoir Dogs', 'Película', 'A botched robbery indicates a police informant, and the pressure mounts in the aftermath at a warehouse. Crime begets violence as the survivors -- veteran Mr. White, newcomer Mr. Orange, psychopathic parolee Mr. Blonde, bickering weasel Mr. Pink and Nice Guy Eddie -- unravel.', 'https://image.tmdb.org/t/p/w200/9L2ZkwMejJzWvYadO0qIg1sMh.jpg', '1992-09-02', 'Crime,Thriller'),
(103, 'Taxi Driver', 'Película', 'A mentally unstable Vietnam War veteran works as a night-time taxi driver in New York City where the perceived decadence and sleaze feed his urge for violent action.', 'https://image.tmdb.org/t/p/w200/ekstpH614fwDX8DUln1a2Opz0N8.jpg', '1976-02-09', 'Crime,Drama'),
(77, 'Memento', 'Película', 'Leonard Shelby is tracking down the man who raped and murdered his wife. The difficulty of locating his wife\'s killer, however, is compounded by the fact that he suffers from a rare, untreatable form of short-term memory loss. Although he can recall details of life before his accident, Leonard cannot remember what happened fifteen minutes ago, where he\'s going, or why.', 'https://image.tmdb.org/t/p/w200/yuNs09hvpHVU1cBTCAk9zxsL2oW.jpg', '2000-10-11', 'Mystery,Thriller'),
(74, 'War for the Planet of the Apes', 'Película', 'Caesar and his apes are forced into a deadly conflict with an army of humans led by a ruthless Colonel. After the apes suffer unimaginable losses, Caesar wrestles with his darker instincts and begins his own mythic quest to avenge his kind.', 'https://image.tmdb.org/t/p/w200/y3AeW200hqFkG7jWJXQpB8g8fqb.jpg', '2017-07-11', 'Drama,Sci-Fi,War'),
(78, 'Blade Runner', 'Película', 'In the smog-choked dystopian Los Angeles of 2019, blade runner Rick Deckard is called out of retirement to terminate a quartet of replicants who have escaped to Earth seeking their creator for a way to extend their short life spans.', 'https://image.tmdb.org/t/p/w200/63N9uyKUfgVDWrZnoYWtwxfqfKJ.jpg', '1982-06-25', 'Sci-Fi,Drama,Thriller'),
(218, 'The Terminator', 'Película', 'In the post-apocalyptic future, reigning tyrannical supercomputers teleport a cyborg assassin known as the "Terminator" back to 1984 to kill Sarah Connor, whose unborn son is destined to lead insurgents against 21st century mechanical hegemony. Meanwhile, the human-resistance movement dispatches a lone warrior to safeguard Sarah. Can he stop the virtually indestructible killing machine?', 'https://image.tmdb.org/t/p/w200/qvktm0BHcnmDpul4Hz01GIazWPr.jpg', '1984-10-26', 'Action,Thriller,Sci-Fi'),
(1891, 'The Empire Strikes Back', 'Película', 'The epic saga continues as Luke Skywalker, in hopes of defeating the evil Galactic Empire, learns the ways of the Jedi from aging master Yoda. But Darth Vader is more determined than ever to capture Luke. Meanwhile, rebel leader Princess Leia, cocky Han Solo, Chewbacca, and droids C-3PO and R2-D2 are thrown into various stages of capture, betrayal and despair.', 'https://image.tmdb.org/t/p/w200/7BuH8itoSrLExs2YZSsM01Qk2no.jpg', '1980-05-20', 'Adventure,Action,Sci-Fi'),
(1892, 'Return of the Jedi', 'Película', 'Luke Skywalker leads a mission to rescue his friend Han Solo from the clutches of Jabba the Hutt, while the Emperor seeks to destroy the Rebellion once and for all with a second dreaded Death Star.', 'https://image.tmdb.org/t/p/w200/jQYlydvHm3kUix1f8prMucrplhm.jpg', '1983-05-25', 'Adventure,Action,Sci-Fi'),
(11, 'Star Wars', 'Película', 'Princess Leia is captured and held hostage by the evil Imperial forces in their effort to take over the galactic Empire. Venturesome Luke Skywalker and dashing captain Han Solo team together with the loveable robot duo R2-D2 and C-3PO to rescue the beautiful princess and restore peace and justice in the Empire.', 'https://image.tmdb.org/t/p/w200/6FfCtAuVAW8XJjZ7eWeLibRLWTw.jpg', '1977-05-25', 'Adventure,Action,Sci-Fi'),
(85, 'Raiders of the Lost Ark', 'Película', 'When Dr. Indiana Jones – the tweed-suited professor who just happens to be a celebrated archaeologist – is hired by the government to locate the legendary Ark of the Covenant, he finds himself up against the entire Nazi regime.', 'https://image.tmdb.org/t/p/w200/ceG9VzoRAVGwcvQqXmHlTQKRAEY.jpg', '1981-06-12', 'Adventure,Action'),
(89, 'Indiana Jones and the Last Crusade', 'Película', 'In 1938, an art collector appeals to eminent archaeologist Dr. Indiana Jones to embark on a search for the Holy Grail. Indy learns that a medieval historian has vanished while searching for it, and the missing man is his own father, Dr. Henry Jones Sr.. He sets out to rescue his father by following clues in the old man\'s notebook, which his father had mailed to him before he went missing. Indy arrives in Venice, where he enlists the help of a beautiful academic, Dr. Elsa Schneider, along with Marcus Brody and Sallah. Together they must stop the Nazis from recovering the power of eternal life and taking over the world!', 'https://image.tmdb.org/t/p/w200/4p1N2Qrt8j0H8xMHMHvtRxv9QP.jpg', '1989-05-24', 'Adventure,Action'),
(87, 'Indiana Jones and the Temple of Doom', 'Película', 'After arriving in India, Indiana Jones is asked by a desperate village to find a mystical stone. He agrees – and stumbles upon a secret cult plotting a terrible plan in the catacombs of an ancient palace.', 'https://image.tmdb.org/t/p/w200/f2nTRKk2zGdUTE7tLJ5EGGSuKA6.jpg', '1984-05-23', 'Adventure,Action'),
(140607, 'Star Wars: The Force Awakens', 'Película', 'Thirty years after defeating the Galactic Empire, Han Solo and his allies face a new threat from the evil Kylo Ren and his army of Stormtroopers.', 'https://image.tmdb.org/t/p/w200/wqnLdwVXoBjKibFRR5U3y0aDUhs.jpg', '2015-12-15', 'Action,Adventure,Sci-Fi'),
(181808, 'Star Wars: The Last Jedi', 'Película', 'Rey develops her newly discovered abilities with the guidance of Luke Skywalker, who is unsettled by the strength of her powers. Meanwhile, the Resistance prepares to do battle with the First Order.', 'https://image.tmdb.org/t/p/w200/kOVEVeg59E0wsnXmF9nrh6OmWII.jpg', '2017-12-13', 'Action,Adventure,Sci-Fi'),
(181812, 'Star Wars: The Rise of Skywalker', 'Película', 'The surviving Resistance faces the First Order once again as the journey of Rey, Finn and Poe Dameron continues. With the power and knowledge of generations behind them, the final battle begins.', 'https://image.tmdb.org/t/p/w200/db32LaOibwEliAmSL2jjDF6oDdj.jpg', '2019-12-18', 'Action,Adventure,Sci-Fi'),
(20001, 'Spirited Away', 'Película', 'A young girl, Chihiro, becomes trapped in a strange new world of spirits. When her parents undergo a mysterious transformation, she must call upon the courage she never knew she had to free her family.', 'https://image.tmdb.org/t/p/w200/39wmItIWsg5sZMyRUHLkWBcuNKq.jpg', '2001-07-20', 'Animation,Family,Fantasy'),
(20002, 'Your Name', 'Película', 'Mitsuha Miyamizu, a high school girl, yearns to live the life of a boy in the bustling city of Tokyo. But one day, she awakens in a room that isn\'t hers and realizes that she has somehow switched places with her classmate Aoi Tōdō, who now has to live Mitsuha\'s life in the humble countryside.', 'https://image.tmdb.org/t/p/w200/q719jGVij9xxE9B8H5FUmMQq9W.jpg', '2016-08-26', 'Animation,Drama,Romance'),
(20003, 'Princess Mononoke', 'Película', 'Ashitaka, a prince of the disappearing Ainu tribe, is cursed by a demonized boar god and must journey to the west to find a cure. Along the way, he encounters San, a young human woman fighting to protect the forest, and Lady Eboshi, who is trying to destroy it. Ashitaka must find a way to bring balance to this conflict.', 'https://image.tmdb.org/t/p/w200/jHWmNr7m544fJ8prMucrplTQKRA.jpg', '1997-07-12', 'Animation,Adventure,Fantasy'),
(20004, 'Akira', 'Película', 'A secret military project endows a group of teenagers with superhuman powers. As they struggle to deal with the consequences, the city of Neo-Tokyo is thrown into chaos.', 'https://image.tmdb.org/t/p/w200/neZ0ykEsPqxamsX6o5pTLF2Y.jpg', '1988-07-16', 'Animation,Action,Sci-Fi'),
(20005, 'Ghost in the Shell', 'Película', 'In the year 2029, the barriers of our world have been broken down by the net and by cybernetics, but this brings new vulnerability to humans in the form of brain-hacking. When a highly-wanted hacker known as \'The Puppetmaster\' begins involving them, Section 9, a group of cybernetically enhanced cops, are called in to investigate and stop the menace.', 'https://image.tmdb.org/t/p/w200/9gvv6REB5YHXeRMsZkVzlZnWb3w.jpg', '1995-11-18', 'Animation,Action,Sci-Fi'),
(20006, 'Blade Runner 2049', 'Película', 'Thirty years after the events of the first film, a new blade runner, LAPD Officer K, unearths a long-buried secret that has the potential to plunge what\'s left of society into chaos. K\'s discovery leads him on a quest to find Rick Deckard, a former LAPD blade runner who has been missing for 30 years.', 'https://image.tmdb.org/t/p/w200/gajva2L0rPYyMJLoGSyQ1Zv43S.jpg', '2017-10-04', 'Sci-Fi,Drama'),
(20007, 'Inception', 'Película', 'Cobb, a skilled thief who commits corporate espionage by infiltrating the subconscious of his targets is offered a chance to regain his old life as payment for a task considered to be impossible: "inception", the implantation of another person\'s idea into a target\'s subconscious.', 'https://image.tmdb.org/t/p/w200/9gk7adHYeDvHkCSEqAvQNLV5Uge.jpg', '2010-07-16', 'Action,Thriller,Sci-Fi,Mystery'),
(20008, 'Interstellar', 'Película', 'The adventures of a group of explorers who make use of a newly discovered wormhole to surpass the limitations on human space travel and conquer the vast distances involved in an interstellar voyage.', 'https://image.tmdb.org/t/p/w200/gEU2QniE6E77NI6lCU6MxlNBvIx.jpg', '2014-11-05', 'Adventure,Drama,Sci-Fi'),
(20009, 'The Matrix', 'Película', 'Set in the 22nd century, The Matrix tells the story of a computer hacker who joins a group of underground insurgents fighting the vast and powerful computers who now rule the earth.', 'https://image.tmdb.org/t/p/w200/f89U3ADr1oiB1s9GkdPOEpXUk5H.jpg', '1999-03-31', 'Action,Sci-Fi'),
(20010, 'The Matrix Reloaded', 'Película', 'Six months after the events depicted in The Matrix, Neo has proved to be a good omen for the free humans, as more and more humans are being freed from the matrix and brought to Zion, the one and only stronghold of the Resistance. Neo himself has discovered his superpowers including super speed, ability to see the codes of the things inside the matrix and a certain degree of pre-cognition.', 'https://image.tmdb.org/t/p/w200/9TGHDvWrqKBzwVmontiQaGjq2m1.jpg', '2003-05-15', 'Action,Sci-Fi'),
(20011, 'The Matrix Revolutions', 'Película', 'The human city of Zion defends itself against the massive invasion of the machines as Neo fights to end the war at another front while also opposing the rogue Agent Smith.', 'https://image.tmdb.org/t/p/w200/sOO0K7L0mCAYHnKm7HO0NgBJTx.jpg', '2003-11-05', 'Action,Sci-Fi');
